	input clk,
	input rst_n,
	input a,
	output reg match
	);

	reg [7:0] a_tem;

	always @(posedge clk or negedge rst_n)
		if (!rst_n)
			begin 
				match <= 1'b0;
			end
		else if (a_tem == 8'b0111_0001)
			begin
				match <= 1'b1;
			end
		else 
